<?php
require_once __DIR__.'/FeedbackPages.php';
function feedback_admin_detail($pdo,$config,$id){
 $service=new FeedbackService($pdo);try{$f=$service->detail($id);}catch(RuntimeException $e){if($e->getMessage()!=='反馈不存在。')throw $e;http_response_code(404);return page('反馈不存在','<div class="empty">反馈不存在。</div>',$config);}
 $old=$_SESSION['_feedback_admin_old'][$id]??array();unset($_SESSION['_feedback_admin_old'][$id]);$labels=array('pending'=>'待审核','rewarded'=>'已通过并奖励','rejected'=>'已驳回');
 $body='<div class="admin-feedback-detail"><a class="secondary-button" href="/admin/feedback">返回列表</a><section class="admin-panel"><h1>'.e($f['subject']).'</h1><p>'.e($f['feedback_no']).' · '.e($f['user_email']??('用户 #'.$f['user_id'])).' · '.e($f['created_at']).' · '.e(array('bug'=>'BUG 反馈','suggestion'=>'功能建议')[$f['type']]??$f['type']).'</p><div class="feedback-body">'.nl2br(e($f['body'])).'</div><h2>审核与奖励</h2><p>'.e($labels[$f['status']]).' · 奖励：'.e(money($f['reward_cents'])).'</p>';
 if($f['status']==='pending')$body.='<form class="feedback-review-form" method="post" action="/admin/feedback/'.(int)$id.'/review">'.csrf_field().'<label>奖励金额（元）<input name="reward_amount" inputmode="decimal" pattern="(?:0|[1-9][0-9]*)(?:\.[0-9]{1,2})?" value="'.e($old['reward_amount']??'').'" placeholder="0.00"></label><label>审核说明（必填）<textarea name="note" maxlength="500" required>'.e(($old['operation']??'')==='review'?($old['note']??''):'').'</textarea></label><button class="button" name="status" value="rewarded">有效并发放奖励</button> <button class="secondary-button" name="status" value="rejected">驳回反馈</button></form>';
 else $body.='<p>'.nl2br(e($f['admin_note'])).'</p>';
 $key=($old['operation']??'')==='progress'&&preg_match('/^[A-Za-z0-9_-]{16,80}$/D',$old['request_key']??'')?$old['request_key']:bin2hex(random_bytes(24));$selected=($old['operation']??'')==='progress'?($old['progress_status']??''):($f['progress_status']??'received');
 $body.=feedback_progress_html($f).'<form class="feedback-review-form" method="post" action="/admin/feedback/'.(int)$id.'/progress">'.csrf_field().'<input type="hidden" name="request_key" value="'.e($key).'"><input type="hidden" name="version" value="'.(int)$f['progress_version'].'"><label>处理进度<select name="progress_status">';foreach(FeedbackService::progressLabels() as $k=>$v)$body.='<option value="'.e($k).'"'.($selected===$k?' selected':'').'>'.e($v).'</option>';
 $body.='</select></label><label>公开进度说明（用户可见，必填）<textarea name="note" maxlength="1000" required>'.e(($old['operation']??'')==='progress'?($old['note']??''):'').'</textarea></label><p class="field-help">可调整或回退；只登记处理安排，不发放余额奖励。</p><button class="button">保存处理进度</button></form></section></div>';page('反馈详情',$body,$config);
}
function register_admin_feedback_routes($router,$pdo,$config){
 $router->get('/admin/feedback',function()use($config,$pdo){Security::requireAdmin();$filters=array();foreach(array('status','type','progress_status') as $k)if(isset($_GET[$k])&&is_string($_GET[$k]))$filters[$k]=$_GET[$k];$page=isset($_GET['page'])&&is_scalar($_GET['page'])?(int)$_GET['page']:1;$data=(new FeedbackService($pdo))->listing($filters,$page,20);$labels=array('pending'=>'待审核','rewarded'=>'已通过并奖励','rejected'=>'已驳回');$rows='';foreach($data['items'] as $f)$rows.='<tr><td><a href="/admin/feedback/'.(int)$f['id'].'">'.e($f['feedback_no']).'</a></td><td>'.e($f['user_email']??('用户 #'.$f['user_id'])).'</td><td>'.e($f['subject']).'</td><td>'.e(array('bug'=>'BUG 反馈','suggestion'=>'功能建议')[$f['type']]??$f['type']).'</td><td>'.e($labels[$f['status']]).'</td><td>'.e(FeedbackService::progressLabels()[$f['progress_status']]??'尚未登记处理进度').'</td><td>'.e($f['created_at']).'</td></tr>';
 $body='<div class="admin-feedback-page">'.admin_heading('反馈与建议','审核奖励与处理进度分别管理。').'<form class="filter" method="get">';foreach(array('status'=>$labels,'type'=>array('bug'=>'BUG 反馈','suggestion'=>'功能建议'),'progress_status'=>array('unregistered'=>'尚未登记处理进度')+FeedbackService::progressLabels()) as $field=>$options){$body.='<select name="'.$field.'"><option value="">全部'.e(array('status'=>'审核状态','type'=>'类型','progress_status'=>'处理进度')[$field]).'</option>';foreach($options as $k=>$v)$body.='<option value="'.e($k).'"'.(($filters[$field]??'')===$k?' selected':'').'>'.e($v).'</option>';$body.='</select>';}$body.='<button class="button">筛选</button></form><section class="admin-panel"><div class="table-wrap"><table><thead><tr><th>编号</th><th>用户邮箱</th><th>主题</th><th>类型</th><th>审核奖励</th><th>处理进度</th><th>时间</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="7" class="empty">暂无反馈。</td></tr>').'</tbody></table></div><p>共 '.(int)$data['total'].' 条 · 第 '.(int)$data['page'].' / '.(int)$data['pages'].' 页</p>';foreach(array(-1=>'上一页',1=>'下一页') as $delta=>$text){$p=$data['page']+$delta;if($p>=1&&$p<=$data['pages'])$body.='<a class="secondary-button" href="/admin/feedback?'.e(http_build_query(array_merge($filters,array('page'=>$p)))).'">'.$text.'</a> ';}$body.='</section></div>';page('反馈与建议',$body,$config);});
 $router->get('/admin/feedback/{id}',function($id)use($config,$pdo){Security::requireAdmin();return feedback_admin_detail($pdo,$config,(int)$id);});
 foreach(array('review','progress') as $operation)$router->post('/admin/feedback/{id}/'.$operation,function($id)use($config,$pdo,$operation){$aid=Security::requireAdmin();post_csrf();$safe=array('operation'=>$operation);foreach(array('status','progress_status','reward_amount','note','request_key','version') as $field)$safe[$field]=isset($_POST[$field])&&is_string($_POST[$field])?$_POST[$field]:'';try{$service=new FeedbackService($pdo);$service->detail((int)$id);if($operation==='review')$service->review((int)$id,$aid,$_POST['status']??'',$_POST['reward_amount']??'0',$_POST['note']??'');else $service->updateProgress((int)$id,$aid,$_POST['progress_status']??'',$_POST['note']??'',$_POST['version']??'',$_POST['request_key']??'');flash('success','反馈处理已保存。');unset($_SESSION['_feedback_admin_old'][(int)$id]);}catch(Exception $e){if($e->getMessage()==='反馈不存在。'){http_response_code(404);return page('反馈不存在','<div class="empty">反馈不存在。</div>',$config);}$_SESSION['_feedback_admin_old'][(int)$id]=$safe;flash('error',$e->getMessage());}redirect('/admin/feedback/'.(int)$id);});
}
